export async function fetchReport(url: string) {
  const rows = [];
  for (let page = 0; ; page++) {
    const res = await fetch(`${url}?page=${page}`, {timeout: 120000});
    const batch = await res.json();
    if (!batch.length) return rows;
    rows.push(...batch);
  }
}

export async function fetchReport(url: string) {
  const res = await fetch(url, { timeout: 30000 });
  return res.json();
}
